import 'package:flutter/material.dart';import 'package:google_maps_flutter/google_maps_flutter.dart';import 'package:flutter/services.dart';import 'dart:ui' as ui;class CustomIconMaps {  static Future<BitmapDescriptor> createCustomMarker(      String imagePath, double rating) async {    final recorder = ui.PictureRecorder();    final canvas = Canvas(recorder);    final size = 80.0;    // download the image    final data = await rootBundle.load(imagePath);    final codec = await ui.instantiateImageCodec(        data.buffer.asUint8List(),        targetWidth: size.round());    final frameInfo = await codec.getNextFrame();    final userImage = frameInfo.image;    // draw image    canvas.drawImage(userImage, Offset.zero, Paint());    // draw background for evaluation    final ratingBgPaint = Paint()..color = Colors.white;    final ratingRect = Rect.fromLTWH(30, 100, 75, 40);    canvas.drawRect(ratingRect, ratingBgPaint);    // draw rating as text    final textPainter = TextPainter(textDirection: TextDirection.ltr);    textPainter.text = TextSpan(      text: rating.toString(),      style: TextStyle(        fontSize: 16,        color: Colors.black,        fontWeight: FontWeight.bold,      ),    );    textPainter.layout();    textPainter.paint(canvas, const Offset(50, 105));    // draw rating as star icon    final starIcon = Icons.star;    final starPainter = TextPainter(textDirection: TextDirection.ltr);    starPainter.text = TextSpan(      text: String.fromCharCode(starIcon.codePoint),      style: TextStyle(        fontSize: 20,        color: Colors.amber,        fontFamily: starIcon.fontFamily,      ),    );    starPainter.layout();    starPainter.paint(canvas, const Offset(40, 13));    // convert to bitmap descriptor    final finalImage = await recorder.endRecording().toImage(          size.round(),          size.round(),        );    final byteData = await finalImage.toByteData(format: ui.ImageByteFormat.png);    final uint8List = byteData!.buffer.asUint8List();    return BitmapDescriptor.bytes(uint8List);  }  static Future<Uint8List> getImageFromRawData(      String image, double width) async {    var imageData = await rootBundle.load(image);    var imageCodec = await ui.instantiateImageCodec(        imageData.buffer.asUint8List(),        targetWidth: width.round());    var imageFrameInfo = await imageCodec.getNextFrame();    var imageBytData =        await imageFrameInfo.image.toByteData(format: ui.ImageByteFormat.png);    return imageBytData!.buffer.asUint8List();  }}